                       (const float*)x.data_ptr<float>(), (float*)y.data_ptr<float>(), n);

    return y;
}
"""

_new_gelu = load_inline(
    name="kb_new_gelu_ext",
    cpp_sources=_gelu_cpp,
    functions=["new_gelu_forward"],
    extra_cflags=["-O3"],
